def argmax_last(xs):
    best = None
    for i, x in enumerate(xs):
        if best is None or x >= xs[best]:
            best = i
    return best

def second_largest(xs):
    top = second = None
    for x in xs:
        if top is None or x > top:
            top, second = x, top
        elif x != top and (second is None or x > second):
            second = x
    return second

def merge_ticks(a, b):
    out, i, j = [], 0, 0
    while i < len(a) and j < len(b):
        if a[i][0] <= b[j][0]:
            out.append(a[i])
            i += 1
        else:
            out.append(b[j])
            j += 1
    return out + a[i:] + b[j:]

def round_trips(trades):
    pos, count = 0, 0
    for t in trades:
        new = pos + t
        if new == 0 and pos != 0:
            count += 1
        pos = new
    return count

def top_symbols(trades, k):
    totals = {}
    for sym, qty in trades:
        totals[sym] = totals.get(sym, 0) + qty
    order = sorted(totals, key=lambda s: (-totals[s], s))
    return order[:k]

def nonneg_walk_counts(n):
    counts = {0: 1}
    for _ in range(n):
        nxt = {}
        for pos, ways in counts.items():
            for step in (1, -1):
                new = pos + step
                if new >= 0:
                    nxt[new] = nxt.get(new, 0) + ways
        counts = nxt
    return counts

